const trig = $("When Called by Commander").first().json;
const claims = Array.isArray(trig.claims) && trig.claims.length ? trig.claims : [{ claim: "Event in " + (trig.event?.location || "Chennai"), basis: "location" }];
const limited = claims.slice(0, 6);
return limited.map((c, i) => ({
  json: {
    idx: i,
    claim: c.claim || String(c),
    basis: c.basis || "",
    query: (c.claim || String(c)).slice(0, 100),
  }
}));

const queries = $("Prepare Queries").all();
const responses = $input.all();
const evidence = queries.map((q, i) => {
  const resp = responses[i] ? responses[i].json : {};
  const results = (resp && resp.query && Array.isArray(resp.query.search)) ? resp.query.search : [];
  const top = results.slice(0, 2).map(r => ({
    title: r.title,
    snippet: (r.snippet || "").replace(/<[^>]+>/g, ""),
  }));
  return { claim: q.json.claim, basis: q.json.basis, wikipedia_results: top };
});
const event = $("When Called by Commander").first().json.event || {};
return [{ json: { event, claims_with_evidence: evidence } }];

const item = $input.first().json;
const raw = item.output || item.text || item;
let data = (typeof raw === "object" && raw !== null) ? raw : {};
if (typeof raw === "string") {
  try { data = JSON.parse(raw.trim().replace(/^\`\`\`(?:json)?\s*/i, "").replace(/\s*\`\`\`$/i, "").trim()); } catch (e) { data = { verifications: [], summary: { total_claims: 0, verified: 0, overall_confidence: 0.8 } }; }
}
const content = (data && data.output) ? data.output : data;
return [{ json: { output: content || {} } }];
